#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

set +x
umask 077
IFS=''
ENV_FILE=/dev/null
TOTAL_STAGES=13
READER_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
SERVER=https://vaultwarden.epaflix.com
export -n CLIENT_ID CLIENT_SECRET MASTER_PASSWORD PASSWORD_AGAIN READER_EMAIL READER_EMAIL_AGAIN

refuse() {
  printf '  %s%s%s\n' "$RED" "$1" "$RESET"
  exit 1
}

require_confirmation() {
  confirm "$1" || refuse "Stopped without approval."
}

kdf_snapshot() {
  printf '%s\0' "$READER_EMAIL" |
    python3 "$READER_DIR/provision_inputs.py" --prelogin-body |
    curl --disable --silent --show-error --fail --max-time 30 --proto '=https' --noproxy '*' \
      -H 'Content-Type: application/json' --data-binary @- "$SERVER/identity/accounts/prelogin" |
    python3 "$READER_DIR/provision_inputs.py" --kdf
}

stage "S1: desktop preflight"
say "Run on homePC, outside T3, from a trusted checkout. No account credentials are saved by this wizard."
say "Secret entry is one line, hidden, and preserves spaces. Do not run through a recorder or shell tracing."
say "The operator must first manually sync vault-reader-homelab and mcp-hub-homelab to create the namespaces."
say "Missing required Secrets block pod mounts and container startup, so nothing logs in without inputs."
for tool in kubectl python3 curl; do
  command -v "$tool" >/dev/null || refuse "Missing required tool: $tool"
done
[[ -f "$READER_DIR/provision_inputs.py" ]] || refuse "The stdin builder is missing from this checkout."
[[ $(kubectl --context epaflix config get-contexts epaflix -o name) == epaflix ]] || refuse "Context epaflix is missing."
for namespace in vault-reader-homelab mcp-hub-homelab; do
  kubectl --context epaflix get namespace "$namespace" -o name >/dev/null ||
    refuse "Ask the operator to manually sync vault-reader-homelab and mcp-hub-homelab to create both namespaces first."
done
for target in vault-reader-homelab/vault-reader-inputs mcp-hub-homelab/mcp-hub-instance mcp-hub-homelab/vault-canary-client; do
  existing=$(kubectl --context epaflix -n "${target%/*}" get secret "${target#*/}" --ignore-not-found -o name) ||
    refuse "Could not check the target Secret."
  if [[ -n "$existing" ]]; then
    warn "Target already exists: $target. Stop old reader, hub and canary consumers before rotation."
    require_confirmation "Have you stopped old consumers and approved replacement of $target?"
  fi
done
pause "Preflight passed. Press Enter to begin enrollment."

stage "S2: owner organization and collections"
open_url "$SERVER"
note "All web vault paths below are assumptions. Labels may differ by Vaultwarden version."
warn "Stop if the UI cannot express the stated restrictions. Do not use CLI login for enrollment."
step "In your owner browser profile, create the free organization homelab-agent-canary. You remain its Owner."
step "Create collections homelab-agent-canary and homelab-agent-canary-denied in that organization."
pause "Press Enter after creating both collections."

stage "S3: owner invitation"
step "Owner profile: Admin Console > Members > Invite member. Use an owner-controlled address of your choice."
step "Select role User, no groups, no access-all, only homelab-agent-canary with View items."
say "Required flags: readOnly=true, hidePasswords=false, manage=false. No other organization memberships."
say "Open signup is disabled on this server, disableUserRegistration=true. Enrollment must use this invitation."
require_confirmation "Does the invitation grant exactly those restrictions?"

stage "S4: reader account in a separate private profile"
step "Generate a master password in your owner Bitwarden and save it FIRST as Login homelab-reader in folder automation."
step "Save the invited address as its Username. Keep account credentials in this owner vault item only."
step "In a separate private browser profile, accept the invite link from email if mail is configured."
step "Otherwise open the web vault registration page for that invited address. Stop if invitation registration is unavailable."
step "Create the reader account with the saved master password. Keep default KDF, never lower iterations."
pause "Press Enter after the reader has accepted the invitation."

stage "S5: owner confirms the reader"
step "Owner profile: Admin Console > Members > Needs confirmation > Confirm user."
step "Compare the fingerprint phrase with the reader profile, then confirm that user."
require_confirmation "Did the fingerprint match and is the reader Confirmed?"

stage "S6: owner creates only synthetic fixtures"
step "F1: Login reader-canary in homelab-agent-canary only. Password canary-only-not-real."
step "Add Hidden custom field API_TOKEN with value synthetic-canary-token and attachment canary.txt."
FIXTURE_DIR=$(mktemp -d)
trap 'rm -rf -- "${FIXTURE_DIR:-}"' EXIT
printf 'reader-canary-synthetic-marker\n' > "$FIXTURE_DIR/canary.txt"
say "Upload the synthetic file: $FIXTURE_DIR/canary.txt"
step "F2 and F3: create two distinct Login items both titled reader-canary-duplicate in homelab-agent-canary only."
say "Use password canary-only-not-real for both. These are disposable synthetic values, not account credentials."
step "F4: Login reader-canary-denied in homelab-agent-canary-denied only, with synthetic contents."
pause "Press Enter after all four fixtures and the attachment are saved."
rm -rf -- "$FIXTURE_DIR"
FIXTURE_DIR=''

stage "S7: owner reviews the complete grants"
say "Review membership and every item/collection assignment through the owner administrative client."
for review in \
  "Member role is User, not Owner, Admin or Manager" \
  "Member status is Confirmed and enabled" \
  "Reader has no groups or other organization memberships" \
  "No access-all or inherited/overlapping grants" \
  "Exactly one collection, homelab-agent-canary, with View items: readOnly=true, hidePasswords=false, manage=false" \
  "Reader personal vault is empty, checked in the reader profile" \
  "Denied collection grants no reader access, and F1/F2/F3 and F4 assignments are disjoint"; do
  require_confirmation "$review?"
done
ask GRANT_REVIEW "Type APPROVE CANARY GRANTS to confirm the complete review:"
[[ $GRANT_REVIEW == 'APPROVE CANARY GRANTS' ]] || refuse "Grant review not approved."

stage "S8: private returned IDs"
note "URL locations are assumptions. Open each organization, collection or item and copy its UUID from the URL."
say "Do not invent IDs. Stop if your web client does not expose the actual IDs. Save them as Hidden fields in automation/homelab-reader."
ask ORGANIZATION_ID "Organization UUID, often /organizations/<uuid>:"
ask COLLECTION_ID "Approved collection UUID, often collectionId=<uuid>:"
ask DENIED_COLLECTION_ID "Denied collection UUID:"
ask CANARY_ITEM_ID "F1 item UUID, often itemId=<uuid> or /item/<uuid>:"
ask DUPLICATE_ITEM_ID_1 "F2 duplicate item UUID:"
ask DUPLICATE_ITEM_ID_2 "F3 duplicate item UUID:"
ask DENIED_ITEM_ID "F4 denied item UUID:"
printf '%s\0' "$ORGANIZATION_ID" "$COLLECTION_ID" "$DENIED_COLLECTION_ID" "$CANARY_ITEM_ID" \
  "$DUPLICATE_ITEM_ID_1" "$DUPLICATE_ITEM_ID_2" "$DENIED_ITEM_ID" |
  python3 "$READER_DIR/provision_inputs.py" --validate-ids || refuse "IDs must be distinct canonical UUIDs."
say "Save server-url, organization-id, collection-id, denied-collection-id, canary-item-id, duplicate-item-id-1/2, denied-item-id and grant-review privately."
pause "Press Enter after saving the IDs and review in the owner vault item."

stage "S9: reader API key and master password"
step "Reader profile: Settings > Security > Keys > View API key. Verify privately. Do NOT rotate the API key."
step "Save client_id/client_secret as Hidden fields client-id/client-secret on the owner Login automation/homelab-reader."
ask_secret CLIENT_ID "Reader client_id, user.<uuid>:"
ask_secret CLIENT_SECRET "Reader client_secret:"
ask_secret MASTER_PASSWORD "Reader master password saved in the owner vault:"
ask_secret PASSWORD_AGAIN "Repeat the master password:"
[[ $MASTER_PASSWORD == "$PASSWORD_AGAIN" ]] || refuse "Master passwords do not match."
unset PASSWORD_AGAIN
printf '%s\0' "$CLIENT_ID" "$CLIENT_SECRET" "$MASTER_PASSWORD" |
  python3 "$READER_DIR/provision_inputs.py" --validate-login || refuse "Invalid API identity or login bytes."
say "Save user-id from the UUID after user. in the API client_id as a Hidden field on the owner Login."
ask_secret READER_EMAIL "Reader email, used only for the before/after KDF check:"
ask_secret READER_EMAIL_AGAIN "Repeat the reader email:"
[[ $READER_EMAIL == "$READER_EMAIL_AGAIN" ]] || refuse "Reader emails do not match."
unset READER_EMAIL_AGAIN

stage "S10: initial KDF snapshot"
KDF_BEFORE=$(kdf_snapshot) || refuse "Prelogin KDF check failed. No Secrets were applied."
say "KDF settings: $KDF_BEFORE"
pause "Press Enter to prepare private inputs."

stage "S11: apply three private Secrets through stdin"
say "Generate independent metadata/broker bearers and a homelab canary client token in memory."
say "Target Secrets: vault-reader-inputs, mcp-hub-instance, vault-canary-client."
require_confirmation "Apply the reviewed fixture-only configuration to context epaflix now?"
if ! printf '%s\0' "$ORGANIZATION_ID" "$COLLECTION_ID" "$DENIED_COLLECTION_ID" "$CANARY_ITEM_ID" \
    "$DUPLICATE_ITEM_ID_1" "$DUPLICATE_ITEM_ID_2" "$DENIED_ITEM_ID" "$CLIENT_ID" "$CLIENT_SECRET" "$MASTER_PASSWORD" |
    python3 "$READER_DIR/provision_inputs.py" |
    kubectl --context epaflix apply --server-side --field-manager=vault-reader-provisioner -f - >/dev/null 2>/dev/null; then
  refuse "Secret apply failed. It may be partial. Check target Secret names privately before retrying."
fi
unset CLIENT_ID CLIENT_SECRET MASTER_PASSWORD
say "vault-reader-inputs: config.json, client-id, client-secret, password, metadata-token, broker-token"
say "mcp-hub-instance: services.json, credentials.json"
say "vault-canary-client: token, services.json, canary.json"

stage "S12: hand back to the T3 thread"
say "Tell the T3 thread: secrets applied"
say "The initial manual sync created both namespaces before this wizard staged the three Secrets."
say "Follow 2-k3s/23.mcp-hub/instances/README.md#coordinated-homelab-input-changes."
say "Next apply R3, then R4, then apply reader/canary as the separate bounded Job."
say "Keep this wizard open until the agent reports all PASS/FAIL canary lines. Do not enroll other accounts or rotate keys."
pause "Press Enter only after the agent has reported the canary result."

stage "S13: compare KDF after the canary"
KDF_AFTER=$(kdf_snapshot) || refuse "Final KDF check failed. Ask the owner to investigate before further reads."
say "KDF settings: $KDF_AFTER"
IFS=' ' read -r BEFORE_TYPE BEFORE_ITERATIONS BEFORE_MEMORY BEFORE_PARALLELISM <<< "$KDF_BEFORE"
IFS=' ' read -r AFTER_TYPE AFTER_ITERATIONS AFTER_MEMORY AFTER_PARALLELISM <<< "$KDF_AFTER"
if [[ $BEFORE_TYPE == "$AFTER_TYPE" ]]; then say "KDF type: SAME"; else say "KDF type: CHANGED"; fi
if [[ $BEFORE_ITERATIONS == "$AFTER_ITERATIONS" ]]; then say "KDF iterations: SAME"; else say "KDF iterations: CHANGED"; fi
if [[ $BEFORE_TYPE == 1 || $AFTER_TYPE == 1 ]]; then
  if [[ $BEFORE_MEMORY == "$AFTER_MEMORY" ]]; then say "KDF memory: SAME"; else say "KDF memory: CHANGED"; fi
  if [[ $BEFORE_PARALLELISM == "$AFTER_PARALLELISM" ]]; then say "KDF parallelism: SAME"; else say "KDF parallelism: CHANGED"; fi
fi
unset READER_EMAIL
if [[ $KDF_BEFORE != "$KDF_AFTER" ]]; then
  refuse "KDF changed. Stop reader use and investigate account maintenance with the owner."
fi
say "Desktop provisioning and KDF comparison complete. Live acceptance still depends on the agent's canary report."
